/// Wszystkie rozmiary, rosnąco.
pub static ALL_SIZES: [u32; 3] = [14, 17, 19];

/// Odległość od gory linii do linii bazowej, w pikselach.
///
/// To jest wysokosc wstepujaca kroju, nie wysokosc litery. Rozninica
/// jest znaczaca: `ó` i `s` nie wchodza do kwadratu wstepujacego, a
/// mylnie liczona bazowa przesuwa wiersz o wysokosc x.
///
/// Plik liniowy na tej wysokosci jest zgodny z `hhea`, a nie z
/// `OS/2.sTypoAscender`: to `hhea` opisuje linie, ktora faktycznie
/// renderuje FreeType, i o ten sam plik pytaliismy przy pomiarach.
pub const ASCENT_14: u32 = 13;
pub const ASCENT_17: u32 = 16;
pub const ASCENT_19: u32 = 18;

/// Glebokosc zejscia kroju, w pikselach. Dodatna.
///
/// Uzywana przy wyliczaniu wysokosci wiersza, gdyby ktos chcial
/// policzyc odstep od polowy x-height zamiast od bazowej.
pub const DESCENT_14: u32 = 3;
pub const DESCENT_17: u32 = 4;
pub const DESCENT_19: u32 = 4;

/// Tabela glifów dla jednego rozmiaru.
///
/// Rozmiar spoza listy to błąd programisty, nie sytuacja do obsługi:
/// `None`, bo brak rozmiaru oznacza błąd atlasu, a nie stan aplikacji.
pub fn table_for(size: u32) -> Option<&'static [Glyph]> {
    match size {
        14 => Some(&GLYPHS_14),
        17 => Some(&GLYPHS_17),
        19 => Some(&GLYPHS_19),
        _ => None,
    }
}

